function drawMenu(){
  // Dark-green stadium atmosphere: soft floodlights, tactical mesh and edge vignette.
  const g=ctx.createLinearGradient(0,0,0,H);
  g.addColorStop(0,'#123d2b');g.addColorStop(.48,'#0b2b20');g.addColorStop(1,'#061713');
  ctx.fillStyle=g;ctx.fillRect(0,0,W,H);

  // Subtle blurred stadium-light bokeh, kept away from the central focal area.
  const lights=[
    [.08,.13,.15,.2],[.2,.08,.1,.14],[.42,.06,.08,.12],
    [.68,.08,.1,.16],[.86,.12,.16,.2],[.96,.28,.1,.14],
    [.05,.72,.1,.14],[.92,.76,.13,.18]
  ];
  lights.forEach(([x,y,r,a])=>{
    const px=W*x,py=H*y,rad=Math.min(W,H)*r;
    const glow=ctx.createRadialGradient(px,py,0,px,py,rad);
    glow.addColorStop(0,'rgba(220,255,226,'+(a*.52)+')');
    glow.addColorStop(.18,'rgba(135,220,177,'+(a*.3)+')');
    glow.addColorStop(1,'rgba(90,180,130,0)');
    ctx.fillStyle=glow;ctx.fillRect(px-rad,py-rad,rad*2,rad*2);
  });

  // Low-contrast tactical geometry/mesh.
  ctx.save();ctx.strokeStyle='rgba(173,220,190,.045)';ctx.lineWidth=Math.max(1,H*.0012);
  const step=Math.max(34,Math.min(W,H)*.12);
  for(let x=-H;x<W+H;x+=step){
    ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x+H*.72,H);ctx.stroke();
    ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x-H*.72,H);ctx.stroke();
  }
  for(let y=H*.18;y<H;y+=step*.72){
    ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();
  }
  ctx.restore();

  // Faint pitch markings preserve the open centre of the composition.
  ctx.save();ctx.strokeStyle='rgba(190,230,204,.085)';ctx.lineWidth=Math.max(1.5,H*.002);
  ctx.beginPath();ctx.arc(W/2,H*.56,Math.min(W*.22,H*.43),0,TAU);
  ctx.moveTo(W/2,H*.13);ctx.lineTo(W/2,H*.99);ctx.stroke();ctx.restore();

  // Dark edge vignette.
  const vr=Math.max(W,H)*.78;
  const vignette=ctx.createRadialGradient(W/2,H*.5,Math.min(W,H)*.18,W/2,H*.5,vr);
  vignette.addColorStop(0,'rgba(0,0,0,0)');
  vignette.addColorStop(.62,'rgba(0,0,0,.12)');
  vignette.addColorStop(1,'rgba(0,0,0,.72)');
  ctx.fillStyle=vignette;ctx.fillRect(0,0,W,H);

  (MS[M.scr]||MS.main)();
  if(toast.t>0)txt(toast.s,W/2,H*.95,H*.045,'#ffe600',800);
}

